#ifndef __CONFIG_933_H__
#define __CONFIG_933_H__

/*==========================================================================*/
/*                                N O T E S                                 */
/*==========================================================================*/
/* This file is included by 'device.h' and represents global compile-time   */
/* configuration parameters.  These parameters can be edited through the    */
/* configuration tool in the RealView IDE.                                  */
/*==========================================================================*/

#define PLATFORM_933
//--------------------------------------------------------------------------//
// <h>  NVFS Library Configuration
// <o0> Base address of NVRAM used
// <i>  Defines the starting point of logical
// <i>  NVRAM memory used by file system.
// <i>
// <i>  Must not be larger than actual NVRAM memory.
// <o1> Size of file system
// <i>  The size in bytes of the file system.
// <i>
// <i>  Make sure that the base address plus this
// <i>  size does not go outside of the logical
// <i>  NVRAM limits.
// <o2> Used OS     <0=> No    <1=> Yes
// <o3> Used Table  <0=> No    <1=> Yes
// <i>  TABLE driven
// </h>

#define NVFS_BASE               0x0000
#define NVFS_SIZE               NVRAM_SIZE
#define NVFS_USE_OS             0x0001
#define CRC_DOW_8_USE_TABLE     0x0001 

#define NVRAM_USE_OS            1

//--------------------------------------------------------------------------//
// Bootload Watchdog Reset Code Addr
extern  unsigned Image$$ER_RAM_BOOT_WDOG_RESET_ID$$Base ;
#define WDOG_RESET_CODE_ADDR ((unsigned) (& Image$$ER_RAM_BOOT_WDOG_RESET_ID$$Base))   

//------------------------------------------------------------------------//
// Application Watchdog Reset Code Addr
extern  unsigned Image$$ER_RAM_APP_WDOG_RESET_ID$$Base ;
#define WDOG_RESET_APP_CODE_ADDR ((unsigned) (& Image$$ER_RAM_APP_WDOG_RESET_ID$$Base))   

//------------------------------------------------------------------------//
// Virtual Watchdog Reset Source Addr
extern  char * Image$$ER_RAM_APP_VWDOG_RESET_SOURCE$$Base ;
#define WDOG_V_RESET_SOURCE_ADDR ((char *) (& Image$$ER_RAM_APP_VWDOG_RESET_SOURCE$$Base))   

//------------------------------------------------------------------------//
// Virtual Watchdog Reset Line Addr
extern  unsigned Image$$ER_RAM_APP_VWDOG_RESET_LINE$$Base ;
#define WDOG_V_RESET_LINE_ADDR ((unsigned) (& Image$$ER_RAM_APP_VWDOG_RESET_LINE$$Base))   

//------------------------------------------------------------------------//
// Virtual Watch timeout period - if not defined, the wdog_v library will set a default value
// Choose these times carefully! some tasks can stay in wake_enter() for a long time
#define VIRTUAL_WATCH_TIMEOUT           5
#define VIRTUAL_WATCH_TIMEOUT_FOR_WAKE  30

// Enable the kicking during the IDLE period
#define WDOG_V_IDLE_MODE_ACTIVE

// Override the PREAMBLE_TIMEOUT definition
#define PREAMBLE_TIMEOUT                5000

//--------------------------------------------------------------------------//
// <h>  CM800 CORE Configuration
// <o0> Out_Q size                          <10-30>
// <i>  Maximum number of out patterns that can run simultaneously
// <o1> Vrtc_F Exec_Q_Msg size              <5-30>
// <i>  Maximum number of Exec_Q_Msg events generated by LIB.VRTC_F
// <o2> CMD buffer size                     <5-30>
// <i>  Maximum number of commands that can buffered by LIB.CMD
// <o3> Cmd Exec_Q_Msg size                 <5-30>
// <i>  Maximum number of Exec_Q_Msg events generated by LIB.CMD
// <o4> Exec Tsk number                     <3-10>
// <i>  The number of Exec task
// <e5> Use LIB.TIMEOUT_Q( only for Falcon )
// <o6> The queue size                      <5-30>
// <i>  Maximum number of Timeout_Q events generated by LIB.TIMEOUT_Q
// </e>
// <e7> Use LIB.LED_USR( for onboard LED patterns - only for Falcon )
// </e>
// <e8> Debug is showing the full text from DEI feature
// </e>
// <e9> Debug is showing the full text from CMD lib
// </e>

// </h>

#define OUT_Q_MAX_SIZE              10
#define VRTC_F_EXEC_Q_MAX_SIZE      5
#define CMD_BUFFER_MAX_SIZE         8
#define CMD_EXEC_Q_MSG_MAX_SIZE     15
#define EXEC_TSK_NUMBER             5
#define TIMEOUT_Q_USED              0
#define TIMEOUT_Q_SIZE              20
#define LED_USR_USED                0
#define DEI_DEBUG_SHOW_FEATURE_FULL 0
#define CMD_SHOW_FULL               0
#define WAKE_DEFAULT_SLEEP_CK       SLEEP_CK_0MHZ

//--------------------------------------------------------------------------//
// <h>  NVRAM Server Tsk Configuration
// <o0> Priority of NVRAM library server <0-65535>
// <i>  Defines the priority of the server encapsulated in 
// <i>  the lib.nvram library.
// <o1> NVRAM Server stack size <0x0000-0xFFFF:4>
// <i>  Defines the NVRAM Server stack size
// </h>
#define NVRAM_SERVER_PRIORITY 65500
#define NVRAM_SERVER_STK      0x340
//--------------------------------------------------------------------------//
// <h>  NVFS Server Tsk Configuration
// <o0> Priority of NVFS library server <0-65535>
// <i>  Defines the priority of the server encapsulated in 
// <i>  the lib.nvfs library.
// <o1> NVFS Server stack size <0x0000-0xFFFF:4>
// <i>  Defines the NVFS Server stack size
// </h>
#define NVFS_SERVER_PRIORITY 65500
#define NVFS_SERVER_STK      0x340
//--------------------------------------------------------------------------//



/*==========================================================================*/

void task_main    (void * tsk_arg) ;

/*==========================================================================*/

#endif

